      "ALTER TABLE \"draft_presence\" ADD CONSTRAINT \"draft_presence_draft_id_drafts_id_fk\" FOREIGN KEY (\"draft_id\") REFERENCES \"public\".\"drafts\"(\"id\") ON DELETE cascade ON UPDATE no action;",
      "ALTER TABLE \"invites\" ADD CONSTRAINT \"invites_player_id_players_id_fk\" FOREIGN KEY (\"player_id\") REFERENCES \"public\".\"players\"(\"id\") ON DELETE set null ON UPDATE no action;",
