      "ALTER TABLE \"opponent_teams\" ADD CONSTRAINT \"opponent_teams_team_id_teams_id_fk\" FOREIGN KEY (\"team_id\") REFERENCES \"public\".\"teams\"(\"id\") ON DELETE cascade ON UPDATE no action;",
      "ALTER TABLE \"account_champion_history\" ADD CONSTRAINT \"account_champion_history_account_id_riot_accounts_id_fk\" FOREIGN KEY (\"account_id\") REFERENCES \"public\".\"riot_accounts\"(\"id\") ON DELETE cascade ON UPDATE no action;",
